<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigHostVO;

trait SmtpOutboundConfigHostAccessor
{
    private SmtpOutboundConfigHostVO $_host;
    public function getHost(): string
    {
        return $this->_host->value();
    }
    public function host(): SmtpOutboundConfigHostVO
    {
        return $this->_host;
    }
    public function isHostChanged(?self $original = null): bool
    {
        return !$this->_host->equals($original?->_host);
    }
    public function withHost(SmtpOutboundConfigHostVO|string $host): self
    {
        $copy = clone $this;
        $copy->_host = SmtpOutboundConfigHostVO::from($host);
        return $copy;
    }
}
